What will be the output of the following error free C code?

```c
#include <stdio.h>
int main()
{
    int i, j;
    for (i = 2; i < 10; i++) {
        for (j = 2; j <= (i/j); j++)
            if (!(i % j))
                break;
        if (j > (i/j))
            printf("%d ", i);
```

What is the output of this C code?

```c
#include <stdio.h>
int main()
{
    int i = 0, j = 0;
    while (i < 5 && j < 10)
    {
        i++;
        j++;
    }
    printf("%d,%d\n", i, j);
    return 0;
}
```

- 5, 5
- 10,10
- 5,10
- error

